export class AuthFacebookService {
  // Base Facebook Graph API URL and API version
  private readonly baseUrl = 'https://graph.facebook.com';
  private readonly apiVersion = 'v23.0';


  /**
   * Retrieves a Facebook user profile using the provided access token.
   * First validates the token, then fetches the user's profile fields.
   * @param loginDto DTO containing the short-lived Facebook access token.
   * @returns Normalized user profile in internal SocialInterface format.
   */

  /**
   * Validates the Facebook access token by calling the /debug_token endpoint.
   * Also ensures the token belongs to our application.
   * @param accessToken The user's short-lived access token to be verified.
   */

  /**
   * Exchanges a short-lived Facebook access token for a long-lived one.
   * Useful for persisting user sessions longer than the default 1–2 hours.
   * @param shortLivedToken Facebook's default short-lived token.
   * @returns A long-lived access token from Facebook.
   */
}

// src/auth-apple/auth-apple.service.ts:16-46 AuthAppleService.getProfileByToken
  async getProfileByToken(
    loginDto: AuthAppleLoginDto,
  ): Promise<SocialInterface> {
    const data = await appleSigninAuth.verifyIdToken(loginDto.idToken, {
      audience: this.configService.get('apple.appAudience', { infer: true }),
    });

    // Apple types this claim as `'true' | 'false' | boolean`, so both truthy
    // forms are matched explicitly and anything else fails closed.
    const emailVerified =
      data.email_verified === true || data.email_verified === 'true';

    // An unverified email must never reach validateSocialLogin: it matches
    // accounts by email, so trusting it would allow account takeover.
    if (data.email && !emailVerified) {
      throw new UnprocessableEntityException({
        status: HttpStatus.UNPROCESSABLE_ENTITY,
        errors: {
          email: 'emailNotVerified',
        },
      });
    }

    return {
      id: data.sub,
      email: data.email,
      emailVerified,
      firstName: loginDto.firstName,
      lastName: loginDto.lastName,
    };
  }

// src/auth-google/auth-google.service.ts:23-62 AuthGoogleService.getProfileByToken
  async getProfileByToken(
    loginDto: AuthGoogleLoginDto,
  ): Promise<SocialInterface> {
    const ticket = await this.google.verifyIdToken({
      idToken: loginDto.idToken,
      audience: [
        this.configService.getOrThrow('google.clientId', { infer: true }),
      ],
    });

    const data = ticket.getPayload();

    if (!data) {
      throw new UnprocessableEntityException({
        status: HttpStatus.UNPROCESSABLE_ENTITY,
        errors: {
          user: 'wrongToken',
        },
      });
    }

    const emailVerified = data.email_verified === true;

    if (data.email && !emailVerified) {
      throw new UnprocessableEntityException({
        status: HttpStatus.UNPROCESSABLE_ENTITY,
        errors: {
          email: 'emailNotVerified',
        },
      });
    }

    return {
      id: data.sub,
      email: data.email,
      emailVerified,
      firstName: data.given_name,
      lastName: data.family_name,
    };
  }

// src/utils/dto/infinity-pagination-response.dto.ts:4-7 InfinityPaginationResponseDto
export class InfinityPaginationResponseDto<T> {
  data: T[];
  hasNextPage: boolean;
}

// src/utils/dto/infinity-pagination-response.dto.ts:9-27 InfinityPaginationResponse
export function InfinityPaginationResponse<T>(classReference: Type<T>) {
  abstract class Pagination {
    @ApiProperty({ type: [classReference] })
    data!: T[];

    @ApiProperty({
      type: Boolean,
      example: true,
    })
    hasNextPage: boolean;
  }

  Object.defineProperty(Pagination, 'name', {
    writable: false,
    value: `InfinityPagination${classReference.name}ResponseDto`,
  });

  return Pagination;
}

// src/utils/infinity-pagination.ts:4-12 infinityPagination
export const infinityPagination = <T>(
  data: T[],
  options: IPaginationOptions,
): InfinityPaginationResponseDto<T> => {
  return {
    data,
    hasNextPage: data.length === options.limit,
  };
};

